function icon_array(){
    $arr = array();
    $html = '';
    $remix = get_icon_list();
    $array_icon = explode(",",$remix);
    foreach($array_icon as $k => $icon){
        $html = 'ri-'.$icon;
        $arr[$k] = $html;
    }
    return $arr;
}

if( ! function_exists( 'my_custom_icons' ) ) {

    function my_custom_icons( $icons ) {
    
        //
        // Use this for reset current icons
        // $icons = array();
    
        //
        // Adding new icons
        $icons[]  = array(
          'title' => 'pix_icon',
          'icons' => icon_array(),
        );
    
        //
        // Move custom icons to top of the list.
        $icons = array_reverse( $icons );
    
        return $icons;
    
      }
      add_filter( 'csf_field_icon_add_icons', 'my_custom_icons' );
    }



  
  